const cost=$('#cost-dialog');$$('[data-cost]').forEach(b=>b.addEventListener('click',()=>cost.showModal()));$('.cost-close')?.addEventListener('click',()=>cost.close());cost?.addEventListener('click',e=>{if(e.target===cost){const r=cost.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)cost.close()}});
