const chrome=[['color-tech.webp','Laptop, telefon i słuchawki','Technologia.','Dobry sprzęt jest gotowy na kolejny rozdział.','phones'],['coins.webp','Złote monety','Kruszec.','Mały przedmiot. Wiele możliwości. Poznaj skup monet.','coins'],['jewelry-cutout.webp','Złote obrączki','Charakter.','Detale, które mówią więcej. Zobacz biżuterię z bliska.','jewelry']];let current=0;function showChrome(i){current=(i+chrome.length)%chrome.length;const d=chrome[current];$('.chrome-object').src='../../assets/'+d[0];$('.chrome-object').alt=d[1];$('#chrome-name').textContent=d[2];$('#chrome-copy').textContent=d[3];$('#chrome-open').dataset.open=d[4];$('#chrome-count').textContent='0'+(current+1)+' / 03';}$('#chrome-next')?.addEventListener('click',()=>showChrome(current+1));$('#chrome-prev')?.addEventListener('click',()=>showChrome(current-1));
